var o=[{title:`Por qué varían los hombros`,text:`El hombro tiene un amplio rango de movimiento y depende de muchos músculos para mantenerse estable. Alcanzar por encima de la cabeza, las posiciones profundas de press y los movimientos rápidos pueden sentirse muy distintos de una persona a otra. Un movimiento restringido o doloroso te dice algo sobre qué ejercicios elegir. No demuestra que tengas una lesión concreta.`},{title:`Ajusta el ejercicio`,text:`Si un press por encima de la cabeza con barra te molesta, prueba un press con mancuernas con agarre neutro, un remo con apoyo o una flexión en la pared. Cambia la profundidad o la dirección antes de añadir resistencia. Los ejercicios de tracción son un buen complemento del press, pero ninguna proporción fija entre empuje y tracción cura el dolor de hombro.`},{title:`Control y exposición gradual`,text:`Mientras aprendes un movimiento, usa repeticiones lentas y controladas, un rango cómodo y cargas ligeras. Desarrollar la fuerza del hombro puede requerir un trabajo cada vez más duro, pero esa progresión no debería empeorar tus síntomas. Forzar un estiramiento a través del dolor o probar una y otra vez levantamientos pesados por encima de la cabeza no te llevará allí más rápido.`},{title:`Señales de aviso`,text:`Busca consejo médico sin demora si tienes dolor intenso tras una caída, un brazo que no puedes mover, una deformidad visible, una hinchazón importante o un entumecimiento nuevo que no desaparece. Los síntomas que no mejoran también necesitan que un profesional los examine.`},{title:`Cómo usar TrainUp`,text:`Añade tu hombro en limitaciones en Perfil, con notas, y mantén actualizada tu lista de equipamiento. El plan elige entonces solo ejercicios que encajan con tus limitaciones, tu equipamiento, tu nivel y tu coordinación. Si un ejercicio duele durante un entrenamiento, toca «Siento dolor» para terminarlo de inmediato. Se queda fuera de tus planes hasta que lo reactives desde Perfil. Cambiar ejercicios de esta manera no trata el pinzamiento, la enfermedad del manguito rotador ni ninguna otra afección concreta.`}];var n=[{label:`NHS: dolor de hombro y señales de alarma`,url:`https://www.nhs.uk/symptoms/shoulder-pain/`},{label:`Declaración de posición del ACSM de 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var r={sections:o,sources:n};export{r as default,o as sections,n as sources};